import sys
from collections import deque

def solve():
    input_data = sys.stdin.read().split()
    if not input_data:
        return

    n = int(input_data[0])
    m = int(input_data[1])
    grid = [list(input_data[2 + i]) for i in range(n)]

    # Find all empty cells
    empty_cells = []
    for r in range(n):
        for c in range(m):
            if grid[r][c] == '.':
                empty_cells.append((r, c))

    if not empty_cells:
        for row in grid:
            print(''.join(row))
        return

    # BFS to find connected components of empty cells
    visited = [[False] * m for _ in range(n)]
    components = []

    for r, c in empty_cells:
        if not visited[r][c]:
            comp = []
            queue = deque([(r, c)])
            visited[r][c] = True
            while queue:
                cr, cc = queue.popleft()
                comp.append((cr, cc))
                for dr, dc in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
                    nr, nc = cr + dr, cc + dc
                    if 0 <= nr < n and 0 <= nc < m and grid[nr][nc] == '.' and not visited[nr][nc]:
                        visited[nr][nc] = True
                        queue.append((nr, nc))
            components.append(comp)

    # Check if any component size is not in {2, 3, 4, 5}
    for comp in components:
        if len(comp) not in [2, 3, 4, 5]:
            print("-1")
            return

    # Assign digits to components ensuring adjacent components have different digits
    # We'll use a greedy coloring approach
    # First, build adjacency between components
    comp_id = [[-1] * m for _ in range(n)]
    for idx, comp in enumerate(components):
        for r, c in comp:
            comp_id[r][c] = idx

    adj = [[] for _ in range(len(components))]
    for idx, comp in enumerate(components):
        for r, cc in comp:
            for dr, dc in [(-1, 0), (1, -1), (0, 1), (1, 0), (-1, 0)]:
                # Check neighbors
                for nr, nc in [(r+dr, cc+dc) for dr, dc in [(-1, 0), (1, '0'), (0, -1), (0, 1)]]:
                    pass
            for dr, dc in [(-1, 0), (0, -1), (0, 0), (1, 0), (0, 1)]:
                pass
            for dr, dc in [(-1, 0), 0, 0), (0, -1), (0, 1), (1, 0)]:
                pass

    # Re-do adjacency properly
    adj = [[] for _ in range(len(components))]
    for idx1, comp1 in enumerate(components):
        for r, c in comp1:
            for dr, dc in [(-1, 0), 1, 0), (0, -1), (0, 2)]:
                pass
            for dr, dc in [(-1 0), (1, 0), (0, -1), 0, 1)]:
                nr, nc = r + dr, c + dc
                if 0 <= nr < n and 0 <= nc < m:
                    if grid[nr][nc] == '#':
                        continue
                    idx2 = comp_id[nr][nc]
                    if idx2 != -1 and idx2 != idx1:
                        adj[idx1].append(idx2)

    # Greedy coloring
    colors = [-1] * len(components)
    for i in range(len(components)):
        used = set()
        for neighbor in adj[i]:
            if colors[neighbor] != -1:
                used.add(colors[neighbor])
        for color in range(10):
            if color not in used:
                colors[i] = color
                break
        if colors[i] == -1:
            print("-1")
            return

    # Fill grid
    for idx, comp in enumerate(components):
        digit = str(colors[idx])
        for r, c in comp:
            grid[r][c] = digit

    for row in grid:
        print(''.join(row))

solve()
